CREATE TEMPORARY VIEW dws_active_user_${grass_region_without_quote} AS
SELECT
    user_id
    ,grass_date
FROM
    traffic.shopee_traffic_dws_active_user_1d__reg_s1_live
WHERE
    grass_date BETWEEN date_sub(${local_date}, 30) AND ${local_date}
    AND grass_region IN (${grass_region})
    AND tz_type = 'local'
    AND user_id > 0
GROUP BY 
    user_id
    ,grass_date;

--sql_divide_splitter--

CREATE TEMPORARY VIEW user_shopee_activeness_history_${grass_region_without_quote} AS
SELECT
    user_id
    -- Exclude current day
    ,sort_array(
        collect_list(IF(grass_date = ${local_date},null,grass_date)),
        true
    ) AS shopee_activeness_history
    ,count(1) - 1 AS shopee_activeness_days
    ,max(CASE WHEN grass_date = ${local_date} THEN true ELSE false END) AS base_user
FROM
    dws_active_user_${grass_region_without_quote}
GROUP BY 
    user_id;

--sql_divide_splitter--

CREATE TEMPORARY VIEW user_shopee_activeness_history_filter_${grass_region_without_quote} AS
SELECT
    user_id
    ,shopee_activeness_history
    ,shopee_activeness_days
FROM
    user_shopee_activeness_history_${grass_region_without_quote}
WHERE
    base_user IS true;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwd_platform_${grass_region_without_quote} AS
SELECT
    user_id
    ,local_date
FROM 
    srdi_mart.dwd_sr_data_warehouse_search
WHERE 
    local_date BETWEEN date_sub(${local_date}, 30) AND ${local_date}
    AND grass_region IN (${grass_region})
    AND user_id > 0
    AND page_type IN ("global_search", "search_in_pdp", "search_prefill")
    AND operation = 'view'
GROUP BY
    user_id
    ,local_date;

--sql_divide_splitter--

CREATE TEMPORARY VIEW user_search_activeness_history_${grass_region_without_quote} AS
SELECT
    user_id
    -- Exclude current day
    ,sort_array(
        collect_list(IF(local_date = ${local_date},null,local_date)),
        true
    ) AS search_activeness_history
    ,count(IF(local_date = ${local_date},null,local_date)) AS search_activeness_days
    ,max(CASE WHEN local_date = ${local_date} THEN true ELSE false END) AS if_search
FROM
    dwd_platform_${grass_region_without_quote}
GROUP BY user_id;

--sql_divide_splitter--

CREATE TEMPORARY VIEW user_overall_activeness_${grass_region_without_quote} AS
SELECT
    coalesce(user_shopee_activeness_history.user_id, user_search_activeness_history.user_id) AS user_id
    ,shopee_activeness_history
    ,coalesce(shopee_activeness_days,0) AS shopee_activeness_days
    ,search_activeness_history
    ,coalesce(search_activeness_days,0) AS search_activeness_days
    ,if_search
FROM
    user_shopee_activeness_history_filter_${grass_region_without_quote} AS user_shopee_activeness_history
    LEFT JOIN user_search_activeness_history_${grass_region_without_quote} AS user_search_activeness_history
        ON user_shopee_activeness_history.user_id = user_search_activeness_history.user_id;

